SELECT AVG(loser_rank) AS average_rank, AVG(loser_rank_points) AS average_rank_points, AVG(loser_rank) AS winner_rank, AVG(loser_rank_points) AS winner_rank_points
FROM matches INNER JOIN rankings ON matches.loser_id = rankings.player_id
WHERE matches.round = 'Round 1' AND matches.year = 2023;

SELECT Addresses.line_1, Addresses.line_2, Addresses.line_3, Addresses.city, Addresses.zip_postcode, Addresses.state_province_county, Addresses.country, Addresses.other_address_details
FROM Addresses
WHERE Addresses.address_id IS NOT NULL;

